      imports = 0;
      signs = 0;
      reads.length = 0;
      mutations = 0;
      const response = await app.request('http://broker.test/v1/puri/token', { method: 'POST', headers: { 'content-type': 'application/json', 'cf-connecting-ip': '203.0.113.33' }, body: JSON.stringify(request) }, env);
